def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, fallback=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return fallback

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_target(start, items, prefer_max=False):
        best_item = None
        best_score = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            score = manhattan(start, p)
            if best_item is None or (prefer_max and score > best_score) or (not prefer_max and score < best_score):
                best_item = p
                best_score = score
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Prefer interception bias over pure chase when possible.
            gw = observation.get("grid_width", 0) or 0
            gh = observation.get("grid_height", 0) or 0
            corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
            if gw and gh:
                far_corner = max(corners, key=lambda c: manhattan(c, opp_pos))
                chase = step_toward(self_pos, opp_pos)
                corner_step = step_toward(self_pos, far_corner)
                if manhattan((sx + chase[0], sy + chase[1]), opp_pos) <= manhattan(self_pos, opp_pos):
                    return chase
                return corner_step
            return step_toward(self_pos, opp_pos)
        # Evader: move away from pursuer; if unknown, drift to far corner.
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        if gw and gh:
            target = max(corners, key=lambda c: manhattan(c, opp_pos))
            away = [sgn(self_pos[0] - opp_pos[0]), sgn(self_pos[1] - opp_pos[1])]
            to_corner = step_toward(self_pos, target)
            if manhattan((sx + away[0], sy + away[1]), opp_pos) >= manhattan(self_pos, opp_pos):
                return away
            return to_corner
        return [sgn(sx - ox), sgn(sy - oy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_target(self_pos, targets, prefer_max=False)
        if target is not None:
            return step_toward(self_pos, target)
        # Fallback: pressure opponent or hold.
        return step_toward(self_pos, opp_pos) if manhattan(self_pos, opp_pos) else [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_target(self_pos, resources, prefer_max=False)
    if target is not None:
        # Small anti-collision bias: if opponent is strictly closer, sidestep toward resource axis.
        d_self = manhattan(self_pos, target)
        d_opp = manhattan(opp_pos, target)
        if d_opp + 1 < d_self:
            dx = sgn(target[0] - sx)
            dy = sgn(target[1] - sy)
            if abs(target[0] - sx) >= abs(target[1] - sy):
                return [dx, 0] if dx != 0 else [0, dy]
            return [0, dy] if dy != 0 else [dx, 0]
        return step_toward(self_pos, target)

    # Fallbacks when no resource-like target exists.
    if env == "resource_collection":
        return step_toward(self_pos, opp_pos)
    return [0, 0]

